# Check if there's a different server or port
import socket

ports_not_reachable = [8000, 3000, 5000, 8080, 8888, 5555, 4200, 4242, 4040, 50050]

for port in ports_not_reachable:
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(1)
        result = s.connect_ex(("localhost", port))
        s.close()
        if result == 0:
            print(f"Port {port} is OPEN")
        else:
            print(f"Port {port} is closed or unavailable")
    except:
        print(f"Port {port}: socket error")

print("\nDone checking ports")

